import{_ as t,c as h,o as i,a2 as g}from"./chunks/framework.B7el9cAC.js";const s=JSON.parse('{"title":"Mục 3.6 – Đạo đức AI","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-3/3.6-dao-duc-ai.md","filePath":"chuong-3/3.6-dao-duc-ai.md","lastUpdated":1775300925000}'),a={name:"chuong-3/3.6-dao-duc-ai.md"};function c(o,n,r,u,l,d){return i(),h("div",null,[...n[0]||(n[0]=[g('<h1 id="muc-3-6-–-đao-đuc-ai" tabindex="-1">Mục 3.6 – Đạo đức AI <a class="header-anchor" href="#muc-3-6-–-đao-đuc-ai" aria-label="Permalink to &quot;Mục 3.6 – Đạo đức AI&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p>Hãy tưởng tượng bạn nộp đơn vào đại học và bị <strong>AI từ chối đơn</strong> — không phải vì học lực kém, mà vì bạn sống ở khu vực có tỷ lệ thất học cao. Hay bạn bị máy quét khuôn mặt <strong>nhận nhầm là nghi phạm</strong> vì AI chưa được huấn luyện đầy đủ với người có ngoại hình như bạn. Hoặc một chatbot tư vấn tâm lý AI <strong>vô tình khuyến khích</strong> điều sai trái vì không hiểu ngữ cảnh.</p><p>Những tình huống này đang xảy ra trong thực tế. Khi AI được dùng để <strong>ra quyết định ảnh hưởng cuộc sống con người</strong>, câu hỏi về đạo đức không còn là lý thuyết nữa.</p><p><strong>Tại sao đạo đức AI quan trọng?</strong> AI ngày càng được dùng trong những quyết định quan trọng: tuyển dụng, cho vay, tuyển sinh, xét xử tội phạm, chẩn đoán y tế. Nếu AI thiên vị hoặc không minh bạch, hậu quả có thể ảnh hưởng đến quyền lợi cơ bản của con người.</p><p><strong>Ví dụ đời thực:</strong></p><ul><li>🏠 <strong>Tại nhà:</strong> Loa thông minh lưu giọng nói của bạn — ai có quyền truy cập dữ liệu đó?</li><li>☕ <strong>Tại quán cafe:</strong> Camera nhận diện khuôn mặt theo dõi thời gian bạn ở lại — có vi phạm quyền riêng tư không?</li><li>🏫 <strong>Tại trường:</strong> AI chấm bài có thể thiên vị học sinh từ vùng có cách viết khác nhau.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="thien-kien-trong-ai-ai-bias" tabindex="-1">Thiên kiến trong AI (AI Bias) <a class="header-anchor" href="#thien-kien-trong-ai-ai-bias" aria-label="Permalink to &quot;Thiên kiến trong AI (AI Bias)&quot;">​</a></h3><p><strong>Thiên kiến (Bias)</strong> trong AI là khi hệ thống AI cho ra kết quả không công bằng, phân biệt đối xử với một nhóm người dựa trên đặc điểm như giới tính, chủng tộc, tuổi tác, địa vị kinh tế.</p><p><strong>Nguồn gốc của thiên kiến:</strong></p><ul><li><strong>Dữ liệu thiên vị:</strong> Nếu dữ liệu huấn luyện phản ánh định kiến xã hội, AI học theo định kiến đó</li><li><strong>Thiếu đa dạng trong dữ liệu:</strong> AI nhận diện khuôn mặt kém hơn với người da màu vì dữ liệu huấn luyện chủ yếu là người da trắng</li><li><strong>Đặc trưng có tương quan:</strong> AI dùng mã bưu điện (khu vực sống) để dự đoán nguy cơ vay không trả — vô tình phân biệt đối xử theo khu vực kinh tế</li></ul><p><strong>Ví dụ thiên kiến AI thực tế:</strong></p><ul><li>Hệ thống tuyển dụng AI của Amazon từ chối CV có từ &quot;phụ nữ&quot; vì được huấn luyện trên dữ liệu lịch sử tuyển dụng chủ yếu là nam giới</li><li>AI nhận diện khuôn mặt nhầm nghi phạm da màu với tỷ lệ cao gấp nhiều lần so với người da trắng</li></ul><h3 id="quyen-rieng-tu-va-du-lieu-ca-nhan" tabindex="-1">Quyền riêng tư và dữ liệu cá nhân <a class="header-anchor" href="#quyen-rieng-tu-va-du-lieu-ca-nhan" aria-label="Permalink to &quot;Quyền riêng tư và dữ liệu cá nhân&quot;">​</a></h3><p>AI cần dữ liệu để học — nhưng dữ liệu đó thường là <strong>thông tin cá nhân</strong> của người dùng.</p><p><strong>Các vấn đề về quyền riêng tư:</strong></p><ul><li><strong>Thu thập dữ liệu không minh bạch:</strong> Người dùng không biết dữ liệu nào được thu thập</li><li><strong>Sử dụng dữ liệu sai mục đích:</strong> Dữ liệu thu thập cho một mục đích nhưng dùng cho mục đích khác</li><li><strong>Rò rỉ dữ liệu:</strong> Dữ liệu cá nhân bị hack, lộ ra ngoài</li><li><strong>Theo dõi không đồng thuận:</strong> Camera nhận diện khuôn mặt theo dõi người dân ở nơi công cộng mà không có sự đồng ý</li></ul><p><strong>GDPR (General Data Protection Regulation):</strong> Luật bảo vệ dữ liệu cá nhân của EU năm 2018 — quy định người dùng có quyền biết, sửa, xóa dữ liệu cá nhân của mình.</p><h3 id="minh-bach-va-giai-thich-đuoc-explainability" tabindex="-1">Minh bạch và giải thích được (Explainability) <a class="header-anchor" href="#minh-bach-va-giai-thich-đuoc-explainability" aria-label="Permalink to &quot;Minh bạch và giải thích được (Explainability)&quot;">​</a></h3><p><strong>AI hộp đen (Black Box AI):</strong> AI đưa ra quyết định nhưng không thể giải thích tại sao. Một mô hình deep learning có thể có hàng tỷ tham số — ngay cả người tạo ra nó cũng không hoàn toàn hiểu tại sao nó ra quyết định đó.</p><p><strong>Vấn đề:</strong> Khi AI từ chối đơn vay tiền của bạn, bạn có quyền biết lý do. Nhưng nếu AI là &quot;hộp đen&quot;, ngân hàng không thể giải thích quyết định đó.</p><p><strong>Explainable AI (XAI):</strong> Nghiên cứu tạo ra AI có thể giải thích lý do ra quyết định theo ngôn ngữ con người hiểu được.</p><h3 id="trach-nhiem-va-trach-nhiem-giai-trinh-accountability" tabindex="-1">Trách nhiệm và trách nhiệm giải trình (Accountability) <a class="header-anchor" href="#trach-nhiem-va-trach-nhiem-giai-trinh-accountability" aria-label="Permalink to &quot;Trách nhiệm và trách nhiệm giải trình (Accountability)&quot;">​</a></h3><p>Khi AI gây ra thiệt hại, <strong>ai chịu trách nhiệm?</strong></p><ul><li>Người phát triển AI?</li><li>Công ty triển khai AI?</li><li>Người dùng AI?</li></ul><p>Ví dụ: Xe tự lái gây tai nạn chết người — công ty sản xuất chịu trách nhiệm hay lái xe &quot;giám sát&quot; chịu trách nhiệm?</p><h3 id="ai-vu-khi-va-su-dung-quan-su" tabindex="-1">AI vũ khí và sử dụng quân sự <a class="header-anchor" href="#ai-vu-khi-va-su-dung-quan-su" aria-label="Permalink to &quot;AI vũ khí và sử dụng quân sự&quot;">​</a></h3><p>AI đang được phát triển cho vũ khí tự động (autonomous weapons) — có thể <strong>tự quyết định tấn công</strong> mà không cần con người phê duyệt. Đây là chủ đề tranh luận đạo đức lớn trong cộng đồng quốc tế.</p><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="tai-sao-ai-thien-vi-du-khong-co-y-đinh" tabindex="-1">Tại sao AI thiên vị dù không &quot;có ý định&quot;? <a class="header-anchor" href="#tai-sao-ai-thien-vi-du-khong-co-y-đinh" aria-label="Permalink to &quot;Tại sao AI thiên vị dù không &quot;có ý định&quot;?&quot;">​</a></h3><p>AI không có ý thức, không có định kiến cá nhân — nhưng nó học từ <strong>dữ liệu của con người, trong xã hội của con người</strong>. Nếu xã hội đó đã có bất bình đẳng (ví dụ: lịch sử tuyển dụng phân biệt giới tính), dữ liệu phản ánh điều đó, và AI học theo.</p><p>Đây giống như một học sinh học lịch sử từ sách giáo khoa cũ có nhiều sai lệch — học sinh không &quot;cố tình sai&quot;, nhưng kiến thức thu được đã sai từ nguồn.</p><h3 id="tai-sao-minh-bach-quan-trong-voi-ai" tabindex="-1">Tại sao &quot;minh bạch&quot; quan trọng với AI? <a class="header-anchor" href="#tai-sao-minh-bach-quan-trong-voi-ai" aria-label="Permalink to &quot;Tại sao &quot;minh bạch&quot; quan trọng với AI?&quot;">​</a></h3><p>Trong xã hội dân chủ, <strong>quyết định ảnh hưởng đến người dân cần có lý do rõ ràng và có thể phản bác</strong>. Nếu AI từ chối đơn bảo lãnh tù của bạn (như hệ thống COMPAS ở Mỹ), bạn có quyền biết và thách thức quyết định đó. AI hộp đen vi phạm quyền cơ bản này.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="qua-trinh-thien-kien-ai-hinh-thanh-nhu-the-nao" tabindex="-1">Quá trình thiên kiến AI hình thành như thế nào <a class="header-anchor" href="#qua-trinh-thien-kien-ai-hinh-thanh-nhu-the-nao" aria-label="Permalink to &quot;Quá trình thiên kiến AI hình thành như thế nào&quot;">​</a></h3><ol><li><strong>Xã hội có bất bình đẳng:</strong> Ví dụ: ngành IT lịch sử có ít phụ nữ hơn nam giới</li><li><strong>Dữ liệu phản ánh hiện thực:</strong> Dữ liệu CV được nhận qua các năm chủ yếu là CV nam</li><li><strong>AI học từ dữ liệu:</strong> AI học rằng &quot;CV nam giới = được nhận nhiều hơn&quot;</li><li><strong>AI triển khai:</strong> Hệ thống tuyển dụng tự động ưu tiên CV nam giới</li><li><strong>Bất bình đẳng được khuếch đại:</strong> AI tuyển dụng ít phụ nữ hơn, dữ liệu tương lai càng lệch hơn</li><li><strong>Vòng phản hồi tiêu cực:</strong> Thiên kiến tự tăng cường theo thời gian</li></ol><h3 id="quy-trinh-phat-trien-ai-co-đao-đuc" tabindex="-1">Quy trình phát triển AI có đạo đức <a class="header-anchor" href="#quy-trinh-phat-trien-ai-co-đao-đuc" aria-label="Permalink to &quot;Quy trình phát triển AI có đạo đức&quot;">​</a></h3><ol><li><strong>Xác định tiêu chí công bằng:</strong> Định nghĩa &quot;công bằng&quot; có nghĩa gì với ứng dụng cụ thể này</li><li><strong>Kiểm tra đa dạng dữ liệu:</strong> Đảm bảo dữ liệu đại diện cho tất cả nhóm người liên quan</li><li><strong>Kiểm tra thiên kiến trước khi triển khai:</strong> Chạy test với các nhóm khác nhau</li><li><strong>Thiết kế giải thích được:</strong> Xây dựng khả năng giải thích quyết định vào hệ thống</li><li><strong>Có cơ chế khiếu nại:</strong> Người bị ảnh hưởng có thể phản đối quyết định của AI</li><li><strong>Giám sát liên tục:</strong> Theo dõi kết quả sau khi triển khai để phát hiện thiên kiến mới</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-thien-kien-trong-bo-loc-cv" tabindex="-1">Ví dụ 1 – Cơ bản: Thiên kiến trong bộ lọc CV <a class="header-anchor" href="#vi-du-1-–-co-ban-thien-kien-trong-bo-loc-cv" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Thiên kiến trong bộ lọc CV&quot;">​</a></h3><p>Một công ty dùng AI sàng lọc CV. AI được huấn luyện trên 10.000 CV của nhân viên thành công từ trước — trong đó 80% là nam giới và tốt nghiệp đại học danh tiếng.</p><p>Kết quả: AI tự động hạ điểm CV của phụ nữ và ứng viên từ trường ít tên tuổi, dù không có quy tắc nào nói vậy. Hậu quả: công ty mất nhiều ứng viên tài năng vì AI thiên kiến.</p><h3 id="vi-du-2-–-đoi-thuc-compas-va-he-thong-tu-phap-hinh-su-my" tabindex="-1">Ví dụ 2 – Đời thực: COMPAS và hệ thống tư pháp hình sự Mỹ <a class="header-anchor" href="#vi-du-2-–-đoi-thuc-compas-va-he-thong-tu-phap-hinh-su-my" aria-label="Permalink to &quot;Ví dụ 2 – Đời thực: COMPAS và hệ thống tư pháp hình sự Mỹ&quot;">​</a></h3><p><strong>COMPAS</strong> là hệ thống AI ở Mỹ dùng để dự đoán khả năng tái phạm tội của bị cáo, ảnh hưởng đến quyết định bảo lãnh và bản án.</p><p>Điều tra của ProPublica (2016) phát hiện: COMPAS dự đoán bị cáo da đen có nguy cơ tái phạm <strong>gấp đôi</strong> thực tế so với bị cáo da trắng. Tức là hệ thống thiên vị chủng tộc một cách có hệ thống — ảnh hưởng trực tiếp đến tự do của con người.</p><p>→ <strong>Bài học:</strong> AI trong hệ thống tư pháp cần được kiểm tra kỹ lưỡng và minh bạch.</p><h3 id="vi-du-3-–-nang-cao-deepfake-va-thao-tung-thong-tin" tabindex="-1">Ví dụ 3 – Nâng cao: Deepfake và thao túng thông tin <a class="header-anchor" href="#vi-du-3-–-nang-cao-deepfake-va-thao-tung-thong-tin" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Deepfake và thao túng thông tin&quot;">​</a></h3><p><strong>Deepfake</strong> là công nghệ AI tạo ra video giả nhưng rất thuyết phục — ghép khuôn mặt người thật vào video giả, hoặc tạo ra giọng nói/hình ảnh của người không có thật.</p><p>Rủi ro đạo đức:</p><ul><li>Tạo video giả của chính khách để lan truyền thông tin sai</li><li>Tạo nội dung khiêu dâm giả với khuôn mặt người thật</li><li>Bằng chứng video không còn đáng tin 100% trong xét xử</li></ul><p>→ <strong>Hậu quả xã hội:</strong> Khi không còn phân biệt được thật/giả trong video, niềm tin xã hội sụp đổ.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="cac-nguyen-tac-đao-đuc-ai" tabindex="-1">Các nguyên tắc đạo đức AI <a class="header-anchor" href="#cac-nguyen-tac-đao-đuc-ai" aria-label="Permalink to &quot;Các nguyên tắc đạo đức AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Ý nghĩa</th><th>Ví dụ áp dụng</th></tr></thead><tbody><tr><td>Công bằng (Fairness)</td><td>AI không phân biệt đối xử</td><td>Kiểm tra thiên kiến trước khi triển khai</td></tr><tr><td>Minh bạch (Transparency)</td><td>Người dùng biết AI đang hoạt động</td><td>Thông báo khi đang nói chuyện với chatbot</td></tr><tr><td>Giải thích được (Explainability)</td><td>Có thể giải thích lý do quyết định</td><td>Ngân hàng giải thích AI từ chối vay vì lý do gì</td></tr><tr><td>Quyền riêng tư (Privacy)</td><td>Bảo vệ dữ liệu cá nhân</td><td>Thu thập tối thiểu, người dùng có quyền xóa</td></tr><tr><td>An toàn (Safety)</td><td>AI không gây hại vật lý</td><td>Xe tự lái phải dừng khi phát hiện nguy hiểm</td></tr><tr><td>Trách nhiệm (Accountability)</td><td>Rõ ràng ai chịu trách nhiệm khi AI sai</td><td>Quy định pháp lý về AI trong y tế, tài chính</td></tr></tbody></table><h3 id="ai-tot-vs-ai-xau-theo-đao-đuc" tabindex="-1">AI tốt vs AI xấu (theo đạo đức) <a class="header-anchor" href="#ai-tot-vs-ai-xau-theo-đao-đuc" aria-label="Permalink to &quot;AI tốt vs AI xấu (theo đạo đức)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>AI có đạo đức</th><th>AI thiếu đạo đức</th></tr></thead><tbody><tr><td>Dữ liệu</td><td>Đa dạng, đại diện, được đồng thuận</td><td>Thiên lệch, thu thập không minh bạch</td></tr><tr><td>Quyết định</td><td>Giải thích được, có thể phản bác</td><td>Hộp đen, không giải thích được</td></tr><tr><td>Tác động</td><td>Giảm bất bình đẳng</td><td>Khuếch đại bất bình đẳng</td></tr><tr><td>Giám sát</td><td>Có con người giám sát</td><td>Hoàn toàn tự động không kiểm soát</td></tr><tr><td>Trách nhiệm</td><td>Rõ ai chịu trách nhiệm</td><td>Trách nhiệm mơ hồ</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li><strong>Thiên kiến AI (Bias)</strong> = AI cho kết quả không công bằng do dữ liệu thiên lệch</li><li><strong>Nguồn gốc thiên kiến:</strong> Dữ liệu phản ánh bất bình đẳng xã hội hiện có</li><li><strong>AI hộp đen</strong> = không giải thích được lý do ra quyết định</li><li><strong>Explainable AI</strong> = AI có thể giải thích quyết định theo ngôn ngữ người hiểu</li><li><strong>Quyền riêng tư:</strong> Người dùng có quyền biết, kiểm soát, xóa dữ liệu cá nhân</li><li><strong>Deepfake</strong> = AI tạo video/ảnh giả nhưng trông thật — rủi ro thao túng thông tin</li><li><strong>6 nguyên tắc đạo đức AI:</strong> Công bằng, Minh bạch, Giải thích được, Quyền riêng tư, An toàn, Trách nhiệm</li><li>AI quyết định về <strong>tự do, y tế, tài chính</strong> của con người cần kiểm tra đặc biệt kỹ</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><p><strong>Câu 1 (Dễ):</strong> Thiên kiến (bias) trong AI là gì? Nêu một ví dụ về thiên kiến AI có thể gây hại trong thực tế.</p><blockquote><p><strong>Đáp án:</strong> Thiên kiến AI là khi hệ thống AI cho ra kết quả không công bằng, phân biệt đối xử với một nhóm người. Ví dụ: AI sàng lọc CV ưu tiên ứng viên nam vì được huấn luyện trên dữ liệu lịch sử tuyển dụng phân biệt giới tính — gây thiệt thòi cho ứng viên nữ tài năng.</p></blockquote><hr><p><strong>Câu 2 (Dễ):</strong> &quot;AI hộp đen&quot; là gì? Tại sao đây là vấn đề đạo đức khi AI được dùng trong xét xử pháp lý?</p><blockquote><p><strong>Đáp án:</strong> AI hộp đen là AI đưa ra quyết định mà không thể giải thích lý do. Trong xét xử pháp lý, bị cáo có quyền hiến định được biết lý do bị kết án và có thể phản bác. Nếu AI kết luận người đó có nguy cơ tái phạm mà không giải thích được, bị cáo không có cách nào thách thức quyết định — vi phạm quyền cơ bản của con người.</p></blockquote><hr><p><strong>Câu 3 (Trung bình):</strong> Một công ty bảo hiểm dùng AI để quyết định phí bảo hiểm sức khỏe. AI sử dụng mã bưu điện (khu vực sống) như một trong các đặc trưng. Điều này có thể gây ra vấn đề đạo đức gì?</p><blockquote><p><strong>Đáp án:</strong> Mã bưu điện có thể là <strong>proxy</strong> cho chủng tộc hoặc tình trạng kinh tế — vì ở nhiều nơi, các nhóm chủng tộc và thu nhập khác nhau sống tập trung ở các khu vực khác nhau. Kết quả: người nghèo hoặc người thuộc nhóm thiểu số sống ở &quot;khu vực rủi ro cao&quot; có thể bị tính phí cao hơn — không phải vì sức khỏe thật sự của họ, mà vì định kiến địa lý. Đây là thiên kiến gián tiếp (proxy discrimination).</p></blockquote><hr><p><strong>Câu 4 (Trung bình):</strong> Nêu 4 trong 6 nguyên tắc đạo đức AI và cho ví dụ cụ thể về cách áp dụng từng nguyên tắc.</p><blockquote><p><strong>Đáp án:</strong></p><ol><li><strong>Công bằng:</strong> Kiểm tra AI tuyển dụng với nhiều nhóm giới tính, chủng tộc trước khi triển khai.</li><li><strong>Minh bạch:</strong> Chatbot hỗ trợ khách hàng phải thông báo rõ &quot;Bạn đang nói chuyện với AI&quot;.</li><li><strong>Quyền riêng tư:</strong> Ứng dụng AI chỉ thu thập dữ liệu cần thiết, người dùng có thể yêu cầu xóa.</li><li><strong>Trách nhiệm:</strong> Quy định rõ công ty phát triển AI y tế chịu trách nhiệm pháp lý nếu AI chẩn đoán sai.</li></ol></blockquote><hr><p><strong>Câu 5 (Ứng dụng):</strong> Một thành phố muốn triển khai hệ thống camera AI nhận diện khuôn mặt để giảm tội phạm. Hãy phân tích 2 lợi ích và 3 vấn đề đạo đức cần giải quyết.</p><blockquote><p><strong>Đáp án gợi ý:</strong><strong>Lợi ích:</strong></p><ol><li>Tốc độ tìm kiếm nghi phạm nhanh hơn nhiều so với xem video thủ công.</li><li>Có thể ngăn chặn tội phạm khi hệ thống nhận ra người có lệnh truy nã đang ở nơi công cộng.</li></ol><p><strong>Vấn đề đạo đức:</strong></p><ol><li><strong>Quyền riêng tư:</strong> Người dân bị theo dõi liên tục mà không đồng thuận — vi phạm quyền tự do đi lại trong không gian công cộng.</li><li><strong>Thiên kiến AI:</strong> Hệ thống có thể nhận nhầm người vô tội, đặc biệt với nhóm thiểu số — dẫn đến bắt giữ oan.</li><li><strong>Lạm dụng quyền lực:</strong> Dữ liệu theo dõi có thể bị dùng để kiểm soát chính trị, đàn áp người biểu tình hợp pháp.</li></ol></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lỗi thường gặp</th><th>Cách hiểu đúng</th></tr></thead><tbody><tr><td>&quot;AI không thiên vị vì nó là máy móc&quot;</td><td>Sai — AI học từ dữ liệu của con người và xã hội, thiên kiến xã hội được mã hóa vào AI nếu không kiểm tra kỹ.</td></tr><tr><td>&quot;Minh bạch AI = công bố mã nguồn&quot;</td><td>Không đủ — minh bạch còn nghĩa là người dùng hiểu AI hoạt động thế nào và tại sao ra quyết định đó.</td></tr><tr><td>&quot;Vấn đề đạo đức AI chỉ là lý thuyết&quot;</td><td>Không — thiên kiến AI đã gây ảnh hưởng thực tế đến tuyển dụng, tín dụng, tư pháp hình sự.</td></tr><tr><td>&quot;Chỉ cần AI chính xác là đủ&quot;</td><td>Sai — AI chính xác 95% trong phân loại nghi phạm vẫn có nghĩa hàng ngàn người vô tội bị ảnh hưởng. Công bằng và chính xác là hai tiêu chí khác nhau.</td></tr><tr><td>&quot;GDPR chỉ áp dụng ở châu Âu&quot;</td><td>GDPR áp dụng cho bất kỳ công ty nào xử lý dữ liệu công dân EU, dù công ty đặt ở đâu. Nhiều nước khác cũng đang xây dựng luật tương tự.</td></tr></tbody></table>',86)])])}const p=t(a,[["render",c]]);export{s as __pageData,p as default};
